mapper.select:
SELECT n.id AS notification_id, m.email AS email, n.title AS title, n.body AS body, n.link AS link FROM notification n JOIN member m ON m.id = n.member_id LEFT JOIN notification_setting s ON s.member_id = n.member_id AND s.type = n.type WHERE n.dedup_key IN
#{dedupKey}
AND n.email_sent_at IS NULL AND COALESCE(s.email_enabled, #{defaultEmailEnabled}) AND m.status IN ('ACTIVE', 'SUSPENDED') AND m.email IS NOT NULL AND m.email_verified_at IS NOT NULL ORDER BY n.id
